# app.R: Shiny-App w02_regression, Woche 2 (Das lineare Modell)
#
# Einfache und multiple Regression, wenn Schlafdauer und Lernzeit korrelieren.
# Spezifikation in 00_Kanon/PLAN_W02.md, Abschnitt 6. Die App verwendet nur
# base R, shiny und ggplot2. Sie läuft lokal mit shiny::runApp() und im Browser
# als shinylive-Export (TECHNIK.md §5, Export mit ../export_apps.R).
#
# Datengenerierender Prozess (Standardwerte wie lernzeit):
#   study_hours ~ N(5; 1,5)
#   sleep_hours = 7 + r * (1,2 / 1,5) * (study_hours - 5) + N(0; 1,2 * sqrt(1 - r^2))
#   exam_score  = 20 + b_sleep * sleep_hours + b_study * study_hours + N(0; sigma)
#
# Erwartungswerte zum Nachrechnen (Leitfaden zu Folie 14 des Seminars):
#   einfache Regression       b_sleep + b_study * r * 1,5 / 1,2,
#                             bei r = -0,55: 2,44, bei r = -0,9: 1,13
#   Standardfehler der        sigma / sqrt(n * 1,2^2 * (1 - r^2)), bei den
#   multiplen Regression      Standardwerten etwa 8 / sqrt(n). Bei r = -0,9 ist
#                             er 1,92-mal so groß wie bei -0,55 und 2,29-mal so
#                             groß wie bei 0
# Die Regler rechnen dieselbe Stichprobe um. Der Standardfehler der multiplen
# Regression ändert sich darin genau um diese Faktoren, bei doppelter
# Fehlerstreuung genau um den Faktor 2.

library(shiny)
library(ggplot2)

# --- Farben und Schrift (TECHNIK.md §4) ----------------------------------------

mv_farben <- c(papier = "#FFFFFF", tinte = "#121212", tinte2 = "#5A5A5A",
               violett = "#5B4B9E", orange = "#B7791F", akzent = "#35638A",
               grau1 = "#BDBDB8", grau2 = "#7A7A76", grau3 = "#3A3A38",
               toenung_o = "#F1E4C9", toenung_v = "#E4DFF1")

# IBM Plex Sans wird verwendet, wenn die Schrift auf dem Rechner installiert
# ist. Im Browser (webR) fehlt sie in der Regel. Dann bleibt der Name leer, und
# das Grafikgerät nimmt seine Standardschrift.
plex_installiert <- function() {
  ordner <- c("~/.fonts", "~/.local/share/fonts", "/usr/share/fonts",
              "/usr/local/share/fonts", "~/Library/Fonts", "/Library/Fonts",
              file.path(Sys.getenv("WINDIR"), "Fonts"),
              file.path(Sys.getenv("LOCALAPPDATA"), "Microsoft", "Windows", "Fonts"))
  treffer <- tryCatch({
    ordner <- ordner[nzchar(ordner) & dir.exists(ordner)]
    list.files(ordner, pattern = "^IBMPlexSans.*\\.(ttf|otf)$",
               recursive = TRUE, ignore.case = TRUE)
  }, error = function(e) character(0))
  length(treffer) > 0
}
schrift <- if (plex_installiert()) "IBM Plex Sans" else ""

# Unter Windows ohne ragg zeichnet Shiny mit dem Windows-Grafikgerät. Es findet
# eine installierte Schrift erst, wenn sie mit windowsFonts() angemeldet ist.
if (nzchar(schrift) && .Platform$OS.type == "windows") {
  anmeldung <- list(grDevices::windowsFont(schrift))
  names(anmeldung) <- schrift
  do.call(grDevices::windowsFonts, anmeldung)
}

# theme_mv() aus 20_Produktion/generator/theme_mv.R, mit der Schrift von oben
theme_mv <- function(base_size = 16) {
  theme_minimal(base_size = base_size, base_family = schrift) +
    theme(
      plot.background  = element_rect(fill = "#FFFFFF", colour = NA),
      panel.background = element_rect(fill = "#FFFFFF", colour = NA),
      panel.grid.minor = element_blank(),
      panel.grid.major = element_line(colour = "#D6D6D2", linewidth = 0.3),
      axis.text        = element_text(colour = "#5A5A5A"),
      axis.title       = element_text(colour = "#121212"),
      strip.text       = element_text(colour = "#121212", hjust = 0),
      legend.position  = "none"
    )
}
schriftgroesse <- 15

# Abbildungen unter 600 Pixeln Breite (Telefon) bekommen kleinere Schrift,
# weniger Achsenbeschriftungen und umbrochene Texte
darstellung <- function(breite_px = NULL) {
  schmal <- !is.null(breite_px) && breite_px < 600
  list(groesse = if (schmal) 12 else schriftgroesse,
       schritt = if (schmal) 4 else 2,
       umbruch = if (schmal) "\n" else " ")
}

# Zahlen mit Dezimalkomma und typografischem Minus
zahl <- function(x, stellen = 2) {
  x <- round(x, stellen)
  x[x == 0] <- 0
  sub("^-", "−", formatC(x, format = "f", digits = stellen, decimal.mark = ","))
}
achse <- function(x) zahl(x, 0)

# Die x-Achse reicht fest von -2 bis 10. Damit bleiben bei den Einstellungen
# aus Vorlesung und Seminar Verschiebungen sichtbar, und Balken über ± 2
# Standardfehler sind lang genug, dass man eine Verdopplung sieht. Nur wenn ein
# Schätzwert, ein Balken oder der wahre Wert darüber hinausreicht, wird die
# Achse in Zweierschritten verlängert, damit nichts verschwindet. Das passiert
# bei kleinem n mit großer Fehlerstreuung und bei extremen Reglerstellungen:
# Der Erwartungswert der einfachen Regression liegt zwischen -5,6 (Regressionsgewicht der
# Schlafdauer 0, Lernzeit 5, r = -0,9) und 13,6 (8, 5, r = 0,9).
x_bereich <- c(-2, 10)
x_grenzen <- function(werte) {
  werte <- werte[is.finite(werte)]
  if (length(werte) == 0) return(x_bereich)
  c(min(x_bereich[1], 2 * floor(min(werte) / 2)),
    max(x_bereich[2], 2 * ceiling(max(werte) / 2)))
}
x_titel <- function(d) paste0("Regressionsgewicht der Schlafdauer", d$umbruch, "(Punkte pro Stunde)")
# Beschriftungen im Abstand d$schritt, bei verlängerter Achse in größeren
# Schritten, damit höchstens etwa 12 / d$schritt Abstände entstehen
x_skala <- function(d, grenzen) {
  breite <- diff(grenzen)
  kandidaten <- c(2, 4, 5, 10, 20, 25, 50, 100)
  kandidaten <- kandidaten[kandidaten >= d$schritt]
  passend <- kandidaten[breite / kandidaten <= 12 / d$schritt]
  schritt <- if (length(passend) == 0) max(kandidaten) else min(passend)
  scale_x_continuous(breaks = seq(schritt * floor(grenzen[1] / schritt),
                                  schritt * ceiling(grenzen[2] / schritt), schritt),
                     labels = achse)
}

# --- Datengenerierender Prozess und Schätzung ----------------------------------

# Standardnormalverteilte Zufallszahlen für 1000 Personen. Spalte 1 erzeugt die
# Lernzeit, Spalte 2 den Fehler der Schlafdauer, Spalte 3 den Fehler der
# Klausurpunkte. Bei n < 1000 zählen die ersten n Zeilen. Die Regler rechnen
# dieselben Zufallszahlen mit neuen Werten um. Neue Zufallszahlen zieht erst
# der Knopf „Eine neue Stichprobe“.
ziehe_z <- function() matrix(rnorm(3 * 1000), ncol = 3)

# Startwert für die erste Stichprobe bei jedem Aufruf der App. Mit ihm liegt die
# erste Stichprobe bei den Einstellungen der Vorlesung (Folie 47) und der
# Aufträge im Seminar (Folie 14) nahe an den Erwartungswerten. Danach zieht die
# App ohne festen Startwert.
startwert <- 1788

# Arbeitet mit Vektoren (eine Stichprobe) und mit Matrizen (eine Stichprobe
# pro Spalte)
erzeuge_daten <- function(z_study, z_sleep, z_error, p) {
  study_hours <- 5 + 1.5 * z_study
  sleep_hours <- 7 + p$r * (1.2 / 1.5) * (study_hours - 5) +
    1.2 * sqrt(1 - p$r^2) * z_sleep
  exam_score <- 20 + p$b_sleep * sleep_hours + p$b_study * study_hours +
    p$sigma * z_error
  list(study_hours = as.matrix(study_hours), sleep_hours = as.matrix(sleep_hours),
       exam_score = as.matrix(exam_score))
}

# Kleinste-Quadrate-Schätzung mit den Formeln für einen und zwei Prädiktoren,
# für alle Spalten (Stichproben) auf einmal. Die Werte stimmen mit
# lm(exam_score ~ sleep_hours + study_hours) und lm(exam_score ~ sleep_hours)
# überein.
schaetze <- function(d) {
  zentriere <- function(m) m - rep(colMeans(m), each = nrow(m))
  x1 <- zentriere(d$sleep_hours)
  x2 <- zentriere(d$study_hours)
  y  <- zentriere(d$exam_score)
  n  <- nrow(y)
  s11 <- colSums(x1 * x1)
  s22 <- colSums(x2 * x2)
  s12 <- colSums(x1 * x2)
  s1y <- colSums(x1 * y)
  s2y <- colSums(x2 * y)
  syy <- colSums(y * y)
  # multiple Regression: exam_score ~ sleep_hours + study_hours
  det <- s11 * s22 - s12^2
  b1 <- (s22 * s1y - s12 * s2y) / det
  b2 <- (s11 * s2y - s12 * s1y) / det
  s2 <- (syy - b1 * s1y - b2 * s2y) / (n - 3)
  # einfache Regression: exam_score ~ sleep_hours
  b_einfach <- s1y / s11
  s2_einfach <- (syy - b_einfach * s1y) / (n - 2)
  data.frame(b_sleep = b1, se_sleep = sqrt(s2 * s22 / det),
             b_study = b2, se_study = sqrt(s2 * s11 / det),
             b_simple = b_einfach, se_simple = sqrt(s2_einfach / s11))
}

# 1000 Stichproben in vier Blöcken zu je 250 Spalten
simuliere <- function(p, anzahl = 1000, block = 250) {
  ergebnis <- vector("list", anzahl / block)
  for (i in seq_along(ergebnis)) {
    z <- function() matrix(rnorm(p$n * block), nrow = p$n)
    ergebnis[[i]] <- schaetze(erzeuge_daten(z(), z(), z(), p))
  }
  do.call(rbind, ergebnis)
}

# --- Abbildungen ---------------------------------------------------------------

abbildung_eine <- function(e, b_wahr, d = darstellung()) {
  modelle <- paste0(c("Multiple", "Einfache"), d$umbruch, "Regression")
  werte <- data.frame(
    modell = factor(modelle, levels = rev(modelle)),
    b = c(e$b_sleep, e$b_simple),
    se = c(e$se_sleep, e$se_simple))
  grenzen <- x_grenzen(c(werte$b - 2 * werte$se, werte$b + 2 * werte$se, b_wahr))
  ggplot(werte, aes(y = modell)) +
    geom_vline(xintercept = b_wahr, colour = mv_farben[["violett"]], linewidth = 0.9) +
    annotate("text", x = b_wahr + 0.25, y = 2.55, label = "wahrer Wert",
             hjust = 0, vjust = 0, size = d$groesse / .pt, family = schrift,
             colour = mv_farben[["violett"]]) +
    geom_segment(aes(x = b - 2 * se, xend = b + 2 * se, yend = modell),
                 colour = mv_farben[["orange"]], linewidth = 1.1) +
    geom_point(aes(x = b), colour = mv_farben[["orange"]], size = 4) +
    x_skala(d, grenzen) +
    scale_y_discrete(expand = expansion(add = c(0.5, 0.75))) +
    coord_cartesian(xlim = grenzen) +
    labs(x = x_titel(d), y = NULL,
         caption = paste0("Punkt: Schätzwert,", d$umbruch,
                          "Balken: \u00b1\u00a02 Standardfehler")) +
    theme_mv(d$groesse) +
    theme(axis.text.y = element_text(colour = mv_farben[["tinte"]], size = rel(1)),
          panel.grid.major.y = element_blank(),
          axis.title.x = element_text(margin = margin(t = 8)),
          plot.caption = element_text(colour = mv_farben[["tinte2"]], hjust = 0,
                                      size = rel(0.9), margin = margin(t = 10)),
          plot.caption.position = "plot")
}

# Gemeinsame Klassenbreite für beide Histogramme, etwa ein Viertel der größeren
# Standardabweichung
klassenbreite <- function(sim) {
  streuung <- max(sd(sim$b_sleep), sd(sim$b_simple))
  kandidaten <- c(0.2, 0.25, 0.5, 1, 2)
  passend <- kandidaten[kandidaten >= streuung / 4]
  if (length(passend) == 0) max(kandidaten) else min(passend)
}

# Höchste Säule, damit beide Histogramme dieselbe y-Achse bekommen. Die
# Klassengrenzen liegen wie in geom_histogram(boundary = b_wahr) am wahren Wert.
hoechste_anzahl <- function(werte, b_wahr, breite) {
  max(table(ceiling((werte - b_wahr) / breite)))
}

# grenzen: gemeinsame x-Achse beider Histogramme, aus hist_grenzen()
abbildung_histogramm <- function(werte, b_wahr, breite, y_max, grenzen,
                                 d = darstellung()) {
  mean_hat <- mean(werte)
  ggplot(data.frame(b = werte), aes(x = b)) +
    geom_histogram(binwidth = breite, boundary = b_wahr,
                   fill = mv_farben[["toenung_o"]], colour = mv_farben[["orange"]],
                   linewidth = 0.35) +
    geom_vline(xintercept = b_wahr, colour = mv_farben[["violett"]], linewidth = 0.9) +
    annotate("text", x = b_wahr + 0.15, y = y_max * 1.3, label = "wahrer Wert",
             hjust = 0, vjust = 1, size = d$groesse / .pt, family = schrift,
             colour = mv_farben[["violett"]]) +
    geom_vline(xintercept = mean_hat, colour = mv_farben[["orange"]], linewidth = 0.9) +
    annotate("text", x = mean_hat + 0.15, y = y_max * 1.3, label = "Schätzwert",
             hjust = 0, vjust = 2.1, size = d$groesse / .pt, family = schrift,
             colour = mv_farben[["orange"]]) +
    x_skala(d, grenzen) +
    scale_y_continuous(labels = achse) +
    coord_cartesian(xlim = grenzen, ylim = c(0, y_max * 1.3)) +
    labs(x = x_titel(d), y = "Anzahl") +
    theme_mv(d$groesse)
}

# Die Achse der Histogramme richtet sich nach den mittleren 99 % der
# Schätzungen beider Modelle, damit einzelne Ausreißer sie nicht verlängern
hist_grenzen <- function(sim, b_wahr) {
  x_grenzen(c(quantile(c(sim$b_sleep, sim$b_simple), c(0.005, 0.995)), b_wahr))
}

kennwerte <- function(werte, b_wahr) {
  paste0("Mittelwert der Schätzungen: ", zahl(mean(werte)),
         "; Standardabweichung: ", zahl(sd(werte)),
         "; Anteil mit weniger als 1 Punkt Abweichung vom wahren Wert: ",
         zahl(100 * mean(abs(werte - b_wahr) < 1), 1), "\u00a0%")
}

# --- Piktogramme der Variablen (STIL.md §2) -------------------------------------

# Dieselben Zeichen wie auf den Folien: Klausurblatt mit Stern für die
# Klausurpunkte, Mond für die Schlafdauer, offenes Buch für die Lernzeit. Sie
# stammen aus 20_Produktion/generator/piktogramme/ (Phosphor Icons, MIT-Lizenz,
# das Klausurblatt mit Stern ist daraus zusammengesetzt) und stehen hier als SVG
# im Quelltext, damit die App eine einzige Datei bleibt. In der Oberfläche steht
# das Piktogramm vor dem Namen der Variable: im Untertitel, an den Reglern und in
# der Tabelle. Piktogramm und Name bleiben beim Umbruch in einer Zeile. Die
# Abbildungen bekommen keines, weil ihre Achse ein Regressionsgewicht zeigt und
# keine Variable.
pikto_svg <- c(
  klausurpunkte = paste0(
    '<path d="M216,40H40A16,16,0,0,0,24,56V216a8,8,0,0,0,11.58,7.16L64,208.94l28.42',
    ',14.22a8,8,0,0,0,7.16,0L128,208.94l28.42,14.22a8,8,0,0,0,7.16,0L192,208.94l28.',
    '42,14.22A8,8,0,0,0,232,216V56A16,16,0,0,0,216,40Zm0,163.06-20.42-10.22a8,8,0,0',
    ',0-7.16,0L160,207.06l-28.42-14.22a8,8,0,0,0-7.16,0L96,207.06,67.58,192.84a8,8,',
    '0,0,0-7.16,0L40,203.06V56H216Z" fill="#121212"/><path d="M128.00,74.00L139.17,',
    '104.63L171.75,105.79L146.07,125.87L155.04,157.21L128.00,139.00L100.96,157.21L1',
    '09.93,125.87L84.25,105.79L116.83,104.63Z" fill="#121212" stroke="#121212" stro',
    'ke-width="10" stroke-linejoin="round"/>'),
  schlafdauer = paste0(
    '<path d="M233.54,142.23a8,8,0,0,0-8-2,88.08,88.08,0,0,1-109.8-109.8,8,8,0,0,0-',
    '10-10,104.84,104.84,0,0,0-52.91,37A104,104,0,0,0,136,224a103.09,103.09,0,0,0,6',
    '2.52-20.88,104.84,104.84,0,0,0,37-52.91A8,8,0,0,0,233.54,142.23ZM188.9,190.34A',
    '88,88,0,0,1,65.66,67.11a89,89,0,0,1,31.4-26A106,106,0,0,0,96,56,104.11,104.11,',
    '0,0,0,200,160a106,106,0,0,0,14.92-1.06A89,89,0,0,1,188.9,190.34Z" fill="#12121',
    '2"/>'),
  lernzeit = paste0(
    '<path d="M232,48H160a40,40,0,0,0-32,16A40,40,0,0,0,96,48H24a8,8,0,0,0-8,8V200a',
    '8,8,0,0,0,8,8H96a24,24,0,0,1,24,24,8,8,0,0,0,16,0,24,24,0,0,1,24-24h72a8,8,0,0',
    ',0,8-8V56A8,8,0,0,0,232,48ZM96,192H32V64H96a24,24,0,0,1,24,24V200A39.81,39.81,',
    '0,0,0,96,192Zm128,0H160a39.81,39.81,0,0,0-24,8V88a24,24,0,0,1,24-24h64Z" fill=',
    '"#121212"/>'))
# pikto("schlafdauer", "Schlafdauer"): das Piktogramm und dahinter der Name
pikto <- function(variable, name) {
  bild <- HTML(paste0('<svg class="pikto" xmlns="http://www.w3.org/2000/svg" ',
                      'viewBox="0 0 256 256" aria-hidden="true" focusable="false">',
                      pikto_svg[[variable]], "</svg>"))
  tags$span(class = "mit-pikto", bild, name)
}

