  title = "Einfache und multiple Regression",
  # Das leere Symbol erspart dem Browser die Anfrage nach favicon.ico
  tags$head(tags$link(rel = "icon", href = "data:,"),
            tags$style(HTML(css)), tags$script(HTML(js))),
  h1("Einfache und multiple Regression"),
  div(class = "untertitel",
      pikto("klausurpunkte", "Klausurpunkte,"),
      pikto("schlafdauer", "Schlafdauer"), "(Stunden pro Nacht) und",
      pikto("lernzeit", "Lernzeit"), "(Stunden pro Tag) in simulierten Daten"),
  sidebarLayout(
    sidebarPanel(
      width = 3,
      sliderInput("n", "Stichprobengröße n", min = 20, max = 1000, value = 180,
                  step = 10, sep = "", ticks = FALSE),
      sliderInput("b_sleep",
                  tagList("Wahres Regressionsgewicht der", pikto("schlafdauer", "Schlafdauer")),
                  min = 0, max = 8, value = 4.5, step = 0.5),
      sliderInput("b_study",
                  tagList("Wahres Regressionsgewicht der", pikto("lernzeit", "Lernzeit")),
                  min = 0, max = 5, value = 3, step = 0.5),
      sliderInput("sigma", "Fehlerstreuung σ", min = 2, max = 20, value = 8,
                  step = 1),
      sliderInput("r",
                  tagList("Korrelation von", pikto("schlafdauer", "Schlafdauer"), "und",
                          pikto("lernzeit", "Lernzeit")),
                  min = -0.9, max = 0.9, value = -0.55, step = 0.05),
      actionButton("neu", "Eine neue Stichprobe", class = "btn-mv"),
