    ),
    mainPanel(
      width = 9,
      tabsetPanel(
        id = "ansicht", type = "hidden",
        tabPanelBody(
          "eine",
          h2(textOutput("titel_eine", inline = TRUE)),
          p(class = "hinweis", "Schätzwerte mit Standardfehler in Klammern"),
