  )
)

# --- Server --------------------------------------------------------------------

server <- function(input, output, session) {

  set.seed(startwert)
  z <- reactiveVal(ziehe_z())
  set.seed(NULL)

  parameter <- reactive({
    req(input$n, input$sigma)
    list(n = input$n, b_sleep = input$b_sleep, b_study = input$b_study,
         sigma = input$sigma, r = input$r)
  })
  # Die 1000 Stichproben werden erst gezogen, wenn ein Regler 0,4 Sekunden
  # stillsteht
  parameter_ruhig <- debounce(parameter, 400)

  observeEvent(input$neu, {
    z(ziehe_z())
    updateTabsetPanel(session, "ansicht", selected = "eine")
  })
  observeEvent(input$tausend, {
    updateTabsetPanel(session, "ansicht", selected = "tausend")
  })

  # Anzeige „Eine Stichprobe“
  eine <- reactive({
    p <- parameter()
    zz <- z()[seq_len(p$n), , drop = FALSE]
    schaetze(erzeuge_daten(zz[, 1], zz[, 2], zz[, 3], p))
  })

  output$titel_eine <- renderText(paste0("Eine Stichprobe mit n = ", parameter()$n))

  output$tabelle <- renderUI({
    e <- eine()
    p <- parameter()
    zelle <- function(b, se) paste0(zahl(b), " (", zahl(se), ")")
    tags$table(
      class = "mv-tabelle",
      tags$thead(tags$tr(
        tags$th(""),
        tags$th(class = "wahr", "Wahrer Wert"),
        tags$th("Multiple Regression"),
        tags$th("Einfache Regression (nur Schlafdauer)"))),
      tags$tbody(
        tags$tr(
          tags$th(scope = "row", "Regressionsgewicht der", pikto("schlafdauer", "Schlafdauer")),
          tags$td(class = "wahr", zahl(p$b_sleep, 1)),
          tags$td(zelle(e$b_sleep, e$se_sleep)),
          tags$td(zelle(e$b_simple, e$se_simple))),
        tags$tr(
          tags$th(scope = "row", "Regressionsgewicht der", pikto("lernzeit", "Lernzeit")),
          tags$td(class = "wahr", zahl(p$b_study, 1)),
          tags$td(zelle(e$b_study, e$se_study)),
          tags$td("")))
    )
  })

  # Breite einer Abbildung im Browser, für darstellung()
  breite <- function(id) session$clientData[[paste0("output_", id, "_width")]]

  output$abb_eine <- renderPlot(
    abbildung_eine(eine(), parameter()$b_sleep, darstellung(breite("abb_eine"))),
    res = 96)

  # Anzeige „1000 Stichproben“. Jeder Klick zieht 1000 neue Stichproben, ebenso
  # jede Änderung an einem Regler, solange diese Anzeige zu sehen ist.
  tausend <- reactive({
    input$tausend
    p <- parameter_ruhig()
    sim <- simuliere(p)
    breite <- klassenbreite(sim)
    list(p = p, sim = sim, breite = breite,
         y_max = max(hoechste_anzahl(sim$b_sleep, p$b_sleep, breite),
                     hoechste_anzahl(sim$b_simple, p$b_sleep, breite)))
  })

  output$titel_tausend <- renderText(
    paste0("1000 Stichproben mit je n = ", tausend()$p$n))

  output$abb_multipel <- renderPlot({
    t <- tausend()
    abbildung_histogramm(t$sim$b_sleep, t$p$b_sleep, t$breite, t$y_max,
                         hist_grenzen(t$sim, t$p$b_sleep),
                         darstellung(breite("abb_multipel")))
  }, res = 96)
  output$kennwerte_multipel <- renderText(
    kennwerte(tausend()$sim$b_sleep, tausend()$p$b_sleep))

  output$abb_einfach <- renderPlot({
    t <- tausend()
    abbildung_histogramm(t$sim$b_simple, t$p$b_sleep, t$breite, t$y_max,
                         hist_grenzen(t$sim, t$p$b_sleep),
                         darstellung(breite("abb_einfach")))
  }, res = 96)
  output$kennwerte_einfach <- renderText(
    kennwerte(tausend()$sim$b_simple, tausend()$p$b_sleep))
}

shinyApp(ui, server)
